# Fragmento de la cabeza dueling, no agente completo.
import torch
from torch import nn
class DuelingHead(nn.Module):
    def __init__(self, features, actions):
        super().__init__()
        self.value=nn.Linear(features,1)
        self.advantage=nn.Linear(features,actions)
    def forward(self,h):
        a=self.advantage(h)
        return self.value(h)+a-a.mean(dim=-1,keepdim=True)

# REINFORCE: loss de gradiente de política.
# log_probs_t guardados durante un episodio;
# returns_t retornos descontados del mismo episodio.
import torch
def reinforce_loss(log_probs_t,returns_t):
    return -(torch.stack(log_probs_t)*returns_t).sum()
